169	    // Directly extend AtomicReference for intrinsics and also to keep memory overhead low.
170	    private final class Entries extends AtomicReference<List<E>> implements Runnable {
171	
172	        private final String hostname;
173	        // Needs to be package-private to be able to access it via the AtomicReferenceFieldUpdater
174	        volatile ScheduledFuture<?> expirationFuture;
175	
176	        Entries(String hostname) {
177	            super(Collections.<E>emptyList());
178	            this.hostname = hostname;
179	        }
