251	        private boolean scheduleCacheExpirationIfNeeded(int ttl, EventLoop loop) {
252	            for (;;) {
253	                // We currently don't calculate a new TTL when we need to retry the CAS as we don't expect this to
254	                // be invoked very concurrently and also we use SECONDS anyway. If this ever becomes a problem
255	                // we can reconsider.
256	                ScheduledFuture<?> oldFuture = FUTURE_UPDATER.get(this);
257	                if (oldFuture == CANCELLED) {
258	                    // This Entries was already evicted from resolveCache by a concurrent expiration.
259	                    // Signal the caller (cache()) to retry with a fresh Entries.
260	                    return false;
261	                }
262	                if (oldFuture == null || oldFuture.getDelay(TimeUnit.SECONDS) > ttl) {
263	                    ScheduledFuture<?> newFuture = loop.schedule(this, ttl, TimeUnit.SECONDS);
264	                    // It is possible that
265	                    // 1. task will fire in between this line, or
266	                    // 2. multiple timers may be set if there is concurrency
267	                    // (1) If the task fires and sets CANCELLED before our CAS, the next loop iteration returns false.
268	                    // (2) This is a trade-off to avoid concurrency resulting in contention on a synchronized block.
269	                    if (FUTURE_UPDATER.compareAndSet(this, oldFuture, newFuture)) {
270	                        if (oldFuture != null) {
271	                            oldFuture.cancel(true);
272	                        }
273	                        return true;
274	                    } else {
275	                        // There was something else scheduled in the meantime... Cancel and try again.
276	                        newFuture.cancel(true);
277	                    }
278	                } else {
279	                    return true;
280	                }
281	            }
282	        }
