284	        boolean clearAndCancel() {
285	            // Set CANCELLED before clearing data so any concurrent scheduleCacheExpirationIfNeeded
286	            // call sees CANCELLED and returns false. If data were cleared first, a concurrent caller
287	            // could win the future CAS (CANCELLED not yet set), return true to cache(), and then
288	            // have its data immediately wiped when CANCELLED is set on the next step.
289	            ScheduledFuture<?> expirationFuture = FUTURE_UPDATER.getAndSet(this, CANCELLED);
290	            List<E> entries = getAndSet(Collections.<E>emptyList());
291	            if (expirationFuture != null && expirationFuture != CANCELLED) {
292	                expirationFuture.cancel(false);
293	            }
294	            return !entries.isEmpty();
295	        }
