302	            // results to the enduser if one of the A or AAAA records has different TTL settings.
303	            //
304	            // As a TTL is just a hint of the maximum time a cache is allowed to cache stuff it's
305	            // completely fine to remove the entry even if the TTL is not reached yet.
306	            //
307	            // See https://github.com/netty/netty/issues/7329
308	            // Set CANCELLED before removing from the map so any concurrent scheduleCacheExpirationIfNeeded
309	            // call always sees CANCELLED and returns false (triggering a retry in cache()) rather than
310	            // succeeding its future CAS, returning true, and having the data wiped immediately after.
311	            clearAndCancel();
312	
313	            resolveCache.remove(hostname, this);
314	        }
315	    }
316	}
