16	package io.netty.handler.codec.quic;
17	
18	import io.netty.util.AsciiString;
19	import io.netty.util.internal.SystemPropertyUtil;
20	import org.jetbrains.annotations.Nullable;
21	
22	import java.util.Iterator;
23	import java.util.LinkedHashMap;
24	import java.util.Map;
25	import java.util.concurrent.atomic.AtomicInteger;
26	
27	final class QuicClientSessionCache {
28	
29	    private static final int DEFAULT_CACHE_SIZE;
30	    static {
31	        // Respect the same system property as the JDK implementation to make it easy to switch between implementations.
32	        int cacheSize = SystemPropertyUtil.getInt("javax.net.ssl.sessionCacheSize", 20480);
33	        if (cacheSize >= 0) {
34	            DEFAULT_CACHE_SIZE = cacheSize;
35	        } else {
36	            DEFAULT_CACHE_SIZE = 20480;
37	        }
38	    }
39	
40	    private final AtomicInteger maximumCacheSize = new AtomicInteger(DEFAULT_CACHE_SIZE);
41	
42	    // Let's use the same default value as OpenSSL does.
43	    // See https://www.openssl.org/docs/man1.1.1/man3/SSL_get_default_timeout.html
44	    private final AtomicInteger sessionTimeout = new AtomicInteger(300);
45	    private int sessionCounter;
46	
47	    private final Map<HostPort, SessionHolder> sessions =
48	            new LinkedHashMap<HostPort, SessionHolder>() {
49	
50	                private static final long serialVersionUID = -7773696788135734448L;
51	
52	                @Override
53	                protected boolean removeEldestEntry(Map.Entry<HostPort, SessionHolder> eldest) {
54	                    int maxSize = maximumCacheSize.get();
55	                    return maxSize >= 0 && size() > maxSize;
56	                }
57	            };
58	
59	    void saveSession(@Nullable String host, int port, long creationTime, long timeout, byte[] session,
60	                     boolean isSingleUse) {
61	        HostPort hostPort = keyFor(host, port);
62	        if (hostPort != null) {
63	            synchronized (sessions) {
64	                // Mimic what OpenSSL is doing and expunge every 255 new sessions
65	                // See https://www.openssl.org/docs/man1.0.2/man3/SSL_CTX_flush_sessions.html
66	                if (++sessionCounter == 255) {
67	                    sessionCounter = 0;
68	                    expungeInvalidSessions();
69	                }
70	
71	                sessions.put(hostPort, new SessionHolder(creationTime, timeout, session, isSingleUse));
72	            }
73	        }
74	    }
75	
76	    // Only used for testing.
77	    boolean hasSession(@Nullable String host, int port) {
78	        HostPort hostPort = keyFor(host, port);
79	        if (hostPort != null) {
80	            synchronized (sessions) {
81	                return sessions.containsKey(hostPort);
82	            }
83	        }
84	        return false;
85	    }
86	
87	    byte @Nullable [] getSession(@Nullable String host, int port) {
88	        HostPort hostPort = keyFor(host, port);
89	        if (hostPort != null) {
90	            SessionHolder sessionHolder;
91	            synchronized (sessions) {
92	                sessionHolder = sessions.get(hostPort);
93	                if (sessionHolder == null) {
94	                    return null;
95	                }
96	                if (sessionHolder.isSingleUse()) {
97	                    // Remove session as it should only be re-used once.
98	                    sessions.remove(hostPort);
99	                }
100	            }
101	            if (sessionHolder.isValid()) {
102	                return sessionHolder.sessionBytes();
103	            }
104	        }
105	        return null;
106	    }
107	
108	    void removeSession(@Nullable String host, int port) {
109	        HostPort hostPort = keyFor(host, port);
110	        if (hostPort != null) {
111	            synchronized (sessions) {
112	                sessions.remove(hostPort);
113	            }
114	        }
115	    }
116	
117	    void setSessionTimeout(int seconds) {
118	        int oldTimeout = sessionTimeout.getAndSet(seconds);
119	        if (oldTimeout > seconds) {
120	            // Drain the whole cache to evict sessions whose server-provided lifetime now
121	            // exceeds the new global maximum. Sessions have heterogeneous per-session
122	            // timeouts so a simple prefix scan cannot identify all newly-expired entries.
123	            clear();
124	        }
125	    }
126	
127	    int getSessionTimeout() {
128	        return sessionTimeout.get();
129	    }
130	
131	    void setSessionCacheSize(int size) {
132	        long oldSize = maximumCacheSize.getAndSet(size);
133	        if (oldSize > size || size == 0) {
134	            // Just keep it simple for now and drain the whole cache.
135	            clear();
136	        }
137	    }
138	
139	    int getSessionCacheSize() {
140	        return maximumCacheSize.get();
141	    }
142	
143	    /**
144	     * Clear the cache and free all cached SSL_SESSION*.
145	     */
146	    void clear() {
147	        synchronized (sessions) {
148	            sessions.clear();
149	        }
150	    }
151	
152	    private void expungeInvalidSessions() {
153	        assert Thread.holdsLock(sessions);
154	
155	        if (sessions.isEmpty()) {
156	            return;
157	        }
158	        long now = System.currentTimeMillis();
159	        Iterator<Map.Entry<HostPort, SessionHolder>> iterator = sessions.entrySet().iterator();
160	        while (iterator.hasNext()) {
161	            SessionHolder sessionHolder = iterator.next().getValue();
162	            if (!sessionHolder.isValid(now)) {
163	                iterator.remove();
164	            }
165	        }
166	    }
167	
168	    @Nullable
169	    private static HostPort keyFor(@Nullable String host, int port) {
170	        if (host == null && port < 1) {
171	            return null;
172	        }
173	        return new HostPort(host, port);
174	    }
175	
176	    private static final class SessionHolder {
177	        private final long creationTime;
178	        private final long timeout;
179	        private final byte[] sessionBytes;
180	        private final boolean isSingleUse;
181	
182	        SessionHolder(long creationTime, long timeout, byte[] session, boolean isSingleUse) {
183	            this.creationTime = creationTime;
184	            this.timeout = timeout;
185	            this.sessionBytes = session;
186	            this.isSingleUse = isSingleUse;
187	        }
188	
189	        boolean isValid() {
190	            return isValid(System.currentTimeMillis());
191	        }
192	
193	        boolean isValid(long current) {
194	            return current <= creationTime + timeout;
195	        }
196	
197	        boolean isSingleUse() {
198	            return isSingleUse;
199	        }
200	
201	        byte[] sessionBytes() {
202	            return sessionBytes;
203	        }
204	    }
205	
206	    /**
207	     * Host / Port tuple used to find a session in the cache.
208	     */
209	    private static final class HostPort {
210	        private final int hash;
211	        private final String host;
212	        private final int port;
213	
214	        HostPort(@Nullable String host, int port) {
215	            this.host = host;
216	            this.port = port;
217	            // Calculate a hashCode that does ignore case. Use -1 for null host to avoid colliding
218	            // with non-null hosts whose AsciiString.hashCode happens to be 0.
219	            this.hash = 31 * (host != null ? AsciiString.hashCode(host) : -1) + port;
220	        }
221	
222	        @Override
223	        public int hashCode() {
224	            return hash;
225	        }
226	
227	        @Override
228	        public boolean equals(Object obj) {
229	            if (!(obj instanceof HostPort)) {
230	                return false;
231	            }
232	            HostPort other = (HostPort) obj;
233	            return port == other.port &&
234	                    (host == null ? other.host == null : host.equalsIgnoreCase(other.host));
235	        }
236	
237	        @Override
238	        public String toString() {
239	            return "HostPort{" +
240	                    "host='" + host + '\'' +
241	                    ", port=" + port +
242	                    '}';
243	        }
244	    }
245	}
