final void clear() {
    while (!resolveCache.isEmpty()) {
        for (Iterator<Entry<String, Entries>> i = resolveCache.entrySet().iterator(); i.hasNext();) {
            Map.Entry<String, Entries> e = i.next();
            i.remove();

            e.getValue().clearAndCancel();
        }
    }
}

