/**
 * Clear all entries (if anything exists) for the given hostname and return {@code true} if anything was removed.
 */
final boolean clear(String hostname) {
    Entries entries = resolveCache.get(hostname);
    if (entries == null) {
        return false;
    }
    // Cancel before removing from the map (consistent with run() ordering).
    boolean hadData = entries.clearAndCancel();
    // Use identity remove so a concurrently-inserted fresh Entries is not accidentally removed.
    resolveCache.remove(hostname, entries);
    return hadData;
}

